import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_an_unconverted_session():
    assert conversion_rate([{"converted": None}, {"converted": True}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_not_groups():
    groups = {"a": [{"converted": False}] * 3, "b": [{"converted": True}], "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 5), (4, 6)])
def test_trailing_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_parse_flags_whitespace_and_skipped_lines():
    assert parse_session_log(["", "   ", "  # header", " a , 2 , 0 ", "b,3,  "]) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,1", "a,Monday,1"])
def test_parse_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["# header", "a,1,1", "", line])


def test_dedupe_keeps_last_record_even_if_its_day_is_earlier():
    events = parse_session_log(["a,5,1", "b,2,1", "c,1,0", "a,2,0"])
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_daily_counts_fill_gaps_and_respect_range():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_session_log(["a,1,1", "b,1,0", "c,4,0"]), "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ranking_and_ordered_rates():
    groups = {"z": [{"converted": True}], "c": [], "a": [{"converted": True}], "b": [{"converted": False}]}
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("c", None), ("z", 1.0)]


def test_nonpositive_counts_break_streaks():
    assert longest_conversion_streak([1, 2, -1, 2, 0, 3]) == 2
    assert longest_conversion_streak([]) == 0
